(4227974, 609687, 30049, '<td valign="top">Nice idea, but would have been MUCH stronger without seeing the background seam.  Good luck in the challenge.</td>', 'Nice idea, but would have been MUCH stronger without seeing the background seam.  Good luck in the challenge.', '2007-11-07 09:34:45.000000', NULL, 1),
