(4236448, 609769, 70689, '<td valign="top">Nice. Great how you maintain subtlety in lighting and dramatic lighting at the same time. Ribbon material, although you will probably suffer from nude-haters voting you down. (8)</td>', 'Nice. Great how you maintain subtlety in lighting and dramatic lighting at the same time. Ribbon material, although you will probably suffer from nude-haters voting you down. (8)', '2007-11-10 03:18:26.000000', NULL, 1),
(4236449, 609717, 73541, '<td valign="top">composition looks too sterile and synthetic. the noise in the picture (if not intentional) could be reduced by freely available software.</td>', 'composition looks too sterile and synthetic. the noise in the picture (if not intentional) could be reduced by freely available software.', '2007-11-10 03:20:05.000000', NULL, 1),
(4236450, 609798, 70689, '<td valign="top">I think your DOF is too shallow for your purpose and it seems like you tried to save it using (too much) USM. Furthermore, I can hardly call this dramatic lighting (3)</td>', 'I think your DOF is too shallow for your purpose and it seems like you tried to save it using (too much) USM. Furthermore, I can hardly call this dramatic lighting (3)', '2007-11-10 03:20:19.000000', NULL, 1),
(4236451, 609679, 68956, '<td valign="top">I really get a sense of a single light source here, it''s given a good range of highlights and shadows. I love the subject matter too. I don''t have a problem with centered compositions, but I''d love to see this with the negative space extended to the left. Well done, you''re one of my top picks :)</td>', 'I really get a sense of a single light source here, it''s given a good range of highlights and shadows. I love the subject matter too. I don''t have a problem with centered compositions, but I''d love to see this with the negative space extended to the left. Well done, you''re one of my top picks :)', '2007-11-10 03:20:39.000000', NULL, 1),
(4236452, 608152, 70689, '<td valign="top">Nice but DNMC (4)</td>', 'Nice but DNMC (4)', '2007-11-10 03:21:01.000000', NULL, 1),
