(4237049, 609687, 35804, '<td valign="top">This has such "sway"...gorgeous light, composition, everything...so very nice.</td>', 'This has such "sway"...gorgeous light, composition, everything...so very nice.', '2007-11-10 13:11:18.000000', NULL, 1),
(4237054, 609782, 35804, '<td valign="top">Fantastic. Simple and powerful..nicely seen.</td>', 'Fantastic. Simple and powerful..nicely seen.', '2007-11-10 13:14:25.000000', NULL, 1),
(4237109, 609679, 30861, '<td valign="top">"her hardest hue to hold..." But frost was talking about her FIRST green, which I''m sure you know :-) Nice shot.</td>', '"her hardest hue to hold..." But frost was talking about her FIRST green, which I''m sure you know :-) Nice shot.', '2007-11-10 13:39:03.000000', NULL, 1),
(4237112, 609245, 30861, '<td valign="top">c''est une orange?</td>', 'c''est une orange?', '2007-11-10 13:41:17.000000', NULL, 1),
(4237119, 609801, 30861, '<td valign="top">Interesting take on the concept of "single"; I count about 50 light sources, but in a very real sense they qualify as "one", metaphysically. I like it!</td>', 'Interesting take on the concept of "single"; I count about 50 light sources, but in a very real sense they qualify as "one", metaphysically. I like it!', '2007-11-10 13:44:58.000000', NULL, 1),
(4237122, 608662, 30861, '<td valign="top">Outstanding</td>', 'Outstanding', '2007-11-10 13:47:11.000000', NULL, 1),
(4237158, 609113, 77543, '<td valign="top">There doesn''t seem to be a connection between the left and right sides of this picture apart from the blue and black tones.</td>', 'There doesn''t seem to be a connection between the left and right sides of this picture apart from the blue and black tones.', '2007-11-10 14:38:16.000000', NULL, 1),
(4237162, 608481, 77543, '<td valign="top">The positioning of the objects in the right of the frame seems odd.</td>', 'The positioning of the objects in the right of the frame seems odd.', '2007-11-10 14:39:03.000000', NULL, 1),
