(4237167, 609860, 77543, '<td valign="top">A bit stark</td>', 'A bit stark', '2007-11-10 14:40:31.000000', NULL, 1),
(4237169, 609402, 77543, '<td valign="top">This seems like it''s suffered from camera shake or subject movement to a slight extent.</td>', 'This seems like it''s suffered from camera shake or subject movement to a slight extent.', '2007-11-10 14:41:21.000000', NULL, 1),
