(4237685, 609687, 77543, '<td valign="top">This looks uncomfortable. The black line at the bottom of the frame should be cropped out.</td>', 'This looks uncomfortable. The black line at the bottom of the frame should be cropped out.', '2007-11-10 20:33:18.000000', NULL, 1),
(4237687, 608916, 60173, '<td valign="top">Without the title, I would have had no idea what this was.<br/> <br/>I know it wouldn''t make practical sense, but maybe some holes in the take-out box with the light shining through would have helped identify it.</td>', 'Without the title, I would have had no idea what this was. I know it wouldn''t make practical sense, but maybe some holes in the take-out box with the light shining through would have helped identify it.', '2007-11-10 20:33:50.000000', NULL, 1),
