(4240312, 608508, 549, '<td valign="top">Cute girl but the light seems to be coming from more than one source. And the contrast is just not there.</td>', 'Cute girl but the light seems to be coming from more than one source. And the contrast is just not there.', '2007-11-12 05:51:29.000000', NULL, 1),
(4240338, 608183, 549, '<td valign="top">Nice and spooky, and you fit the bill for one light source! Bravo.</td>', 'Nice and spooky, and you fit the bill for one light source! Bravo.', '2007-11-12 06:02:43.000000', NULL, 1),
(4240507, 608986, 84668, '<td valign="top">Use a single, artificial light source to dramatically light the subject of your choice.</td>', 'Use a single, artificial light source to dramatically light the subject of your choice.', '2007-11-12 08:33:47.000000', NULL, 1),
(4240535, 608800, 81382, '<td valign="top">Could be a bit sharper in the center with greater DOF</td>', 'Could be a bit sharper in the center with greater DOF', '2007-11-12 08:58:53.000000', NULL, 1),
(4240539, 609312, 81382, '<td valign="top">A bit blurrey i''m afraid, difficult at night I know. It doesn''t look that noisy though so perhaps you could have pushed the ISO harder to reduce the shutter time and sharpen up the image</td>', 'A bit blurrey i''m afraid, difficult at night I know. It doesn''t look that noisy though so perhaps you could have pushed the ISO harder to reduce the shutter time and sharpen up the image', '2007-11-12 08:59:57.000000', NULL, 1),
