(4242934, 609424, 5112, '<td valign="top">Beautiful lighting.</td>', 'Beautiful lighting.', '2007-11-13 00:42:58.000000', NULL, 1),
(4242938, 609782, 5112, '<td valign="top">I don''t know what this is really, but it''s very good to look at.  Looks like the shell of an insect and some other items?  Beautiful tones.</td>', 'I don''t know what this is really, but it''s very good to look at.  Looks like the shell of an insect and some other items?  Beautiful tones.', '2007-11-13 00:45:17.000000', NULL, 1),
(4242939, 609801, 5112, '<td valign="top">Oh, my, not already I hope!  I bet you''re getting comments that there''s more than one light here.  Well, so they are :P  ~7</td>', 'Oh, my, not already I hope!  I bet you''re getting comments that there''s more than one light here.  Well, so they are :P  ~7', '2007-11-13 00:46:19.000000', NULL, 1),
(4242946, 609861, 5112, '<td valign="top">Beautiful colours on that leaf.  The focus is off, IMO, the front part (closest to the viewer) should be sharp here for the image to work well, probably the whole leaf.  Since it''s sitting there on a white background (no wind, no interferences in the fore/background), a longer exposure might do the trick.</td>', 'Beautiful colours on that leaf.  The focus is off, IMO, the front part (closest to the viewer) should be sharp here for the image to work well, probably the whole leaf.  Since it''s sitting there on a white background (no wind, no interferences in the fore/background), a longer exposure might do the trick.', '2007-11-13 00:48:18.000000', NULL, 1),
(4242948, 609903, 5112, '<td valign="top">Beautiful fall leaves image!  Perfect control of light and of DOF.  Very good to look at.  ~9</td>', 'Beautiful fall leaves image!  Perfect control of light and of DOF.  Very good to look at.  ~9', '2007-11-13 00:49:25.000000', NULL, 1),
(4242957, 608554, 5112, '<td valign="top">Wow, beautiful action shot!  ~10</td>', 'Wow, beautiful action shot!  ~10', '2007-11-13 00:53:50.000000', NULL, 1),
(4242960, 608794, 5112, '<td valign="top">The light is a little harsh in this image (or maybe it''s just overexposed).</td>', 'The light is a little harsh in this image (or maybe it''s just overexposed).', '2007-11-13 00:54:47.000000', NULL, 1),
(4242962, 608634, 5112, '<td valign="top">Awwww, so sweet!</td>', 'Awwww, so sweet!', '2007-11-13 00:56:00.000000', NULL, 1),
(4242970, 609667, 5112, '<td valign="top">Looks sexy!</td>', 'Looks sexy!', '2007-11-13 00:58:30.000000', NULL, 1),
(4242977, 608306, 5112, '<td valign="top">Beautiful light!</td>', 'Beautiful light!', '2007-11-13 01:05:15.000000', NULL, 1),
(4243073, 609301, 81382, '<td valign="top">Would have been better being much closer to the model, only the top half of the body perhaps, with focus on the head and huge DOF. Then the shadows and awkward specular highlights wouldn''t have come into play</td>', 'Would have been better being much closer to the model, only the top half of the body perhaps, with focus on the head and huge DOF. Then the shadows and awkward specular highlights wouldn''t have come into play', '2007-11-13 03:25:47.000000', NULL, 1),
(4243082, 608916, 81382, '<td valign="top">Nicely lit, not so sure about the composition though, would have lost some of the black space at the bottom and on the right hand side perhaps</td>', 'Nicely lit, not so sure about the composition though, would have lost some of the black space at the bottom and on the right hand side perhaps', '2007-11-13 03:30:16.000000', NULL, 1),
(4243084, 609424, 81382, '<td valign="top">A lovely shot, great sharpness on the eyes, good DOF, clean background, good composition. Perhaps could have pushes the saturation a little</td>', 'A lovely shot, great sharpness on the eyes, good DOF, clean background, good composition. Perhaps could have pushes the saturation a little', '2007-11-13 03:32:11.000000', NULL, 1),
(4243091, 608508, 81382, '<td valign="top">Indoor flash always produces harsh unsightly shadows on the backdrop. Could have pushed the tonal range harder at the bottom end and given its mono, could have clipped the tonal extremes to make for a more dramatic image</td>', 'Indoor flash always produces harsh unsightly shadows on the backdrop. Could have pushed the tonal range harder at the bottom end and given its mono, could have clipped the tonal extremes to make for a more dramatic image', '2007-11-13 03:34:39.000000', NULL, 1),
(4243097, 609744, 81382, '<td valign="top">Burnt out in the flame, this is your main focal point and it has no detail to it which is a shame. You could have cropped in a fair amount too. A very wide angle would have made it more abstrast and added to it IMO</td>', 'Burnt out in the flame, this is your main focal point and it has no detail to it which is a shame. You could have cropped in a fair amount too. A very wide angle would have made it more abstrast and added to it IMO', '2007-11-13 03:36:52.000000', NULL, 1),
(4243131, 609798, 14437, '<td valign="top">Yummy :) The single light source is not clearly define in this shot though.</td>', 'Yummy :) The single light source is not clearly define in this shot though.', '2007-11-13 05:02:08.000000', NULL, 1),
