(4243318, 609720, 6999, '<td valign="top">I like this: well, perhaps that''s a bit strong: I like the difference of it, like that its entered here where it will of course not win. It has a certain madness of intent to it that fascinates.<br/> <br/><img alt="'' . substr(''//www.edclarke.org.uk/useful/my_red.gif'', strrpos(''//www.edclarke.org.uk/useful/my_red.gif'', ''/'') + 1) . ''" border="0" src="//www.edclarke.org.uk/useful/my_red.gif"/></td>', 'I like this: well, perhaps that''s a bit strong: I like the difference of it, like that its entered here where it will of course not win. It has a certain madness of intent to it that fascinates. ', '2007-11-13 08:28:43.000000', NULL, 1),
(4243394, 609667, 86589, '<td valign="top">Beautiful! Not only great lighting, the water adds a nice feeling of cool temperature.</td>', 'Beautiful! Not only great lighting, the water adds a nice feeling of cool temperature.', '2007-11-13 08:57:12.000000', NULL, 1),
