(4244124, 609315, 69102, '<td valign="top">great depth of field, but i wish the point of focus was on his eyes and not the ridge of the eyebrow/tip of the nose.</td>', 'great depth of field, but i wish the point of focus was on his eyes and not the ridge of the eyebrow/tip of the nose.', '2007-11-13 15:02:25.000000', NULL, 1),
(4244129, 607271, 48588, '<td valign="top">The box on the right is distracting.  I think the white space on either side of the image definitely takes away from it, and should have been removed.</td>', 'The box on the right is distracting.  I think the white space on either side of the image definitely takes away from it, and should have been removed.', '2007-11-13 15:04:36.000000', NULL, 1),
