(4244138, 608152, 47091, '<td valign="top">Good photo but more than one light source.</td>', 'Good photo but more than one light source.', '2007-11-13 15:09:42.000000', NULL, 1),
(4244140, 607776, 47091, '<td valign="top">More than one light source</td>', 'More than one light source', '2007-11-13 15:10:24.000000', NULL, 1),
(4244169, 609912, 77192, '<td valign="top">nicely captured</td>', 'nicely captured', '2007-11-13 15:26:49.000000', NULL, 1),
