(4244793, 609392, 30214, '<td valign="top">interesting concept</td>', 'interesting concept', '2007-11-13 19:36:32.000000', NULL, 1),
(4244794, 609943, 30214, '<td valign="top">lovely</td>', 'lovely', '2007-11-13 19:36:43.000000', NULL, 1),
(4244796, 609483, 70036, '<td valign="top">Intriguing image, but...   There is natural light and more than one source of light. Sorry.</td>', 'Intriguing image, but...   There is natural light and more than one source of light. Sorry.', '2007-11-13 19:37:28.000000', NULL, 1),
