INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4246757, 608965, 64446, '<td valign="top">Excellent image, so pleasant to comtemplate! You are really cooking, eh? No wonder your laptop fried... Congratulations on your ribbon!</td>', 'Excellent image, so pleasant to comtemplate! You are really cooking, eh? No wonder your laptop fried... Congratulations on your ribbon!', '2007-11-14 11:51:43.000000', NULL, 0),
(4246765, 609318, 64446, '<td valign="top">Terrific image! Many congrats!!!</td>', 'Terrific image! Many congrats!!!', '2007-11-14 11:53:23.000000', NULL, 0),
(4246822, 609782, 7778, '<td valign="top">Textures, colour, raked lighting, tones, all these draw attention to much immaculate detail. The composition, however, is bold combining thirds and forths against a deep black space bleeding away the dimensions of objects framing it. This, of course, introduces some ambiguity via areas (inner vertical bone on the left and insect remains so sparsely lit, it is a challenge to identify). Very little visual information is given to go beyond guessing as to what exactly the three objects are that combine this image, which leaves us with mystery.<br/> <br/>What intrigues me though, is the balance of tack-sharp poise of detail (the obvious image facts) versus its opposite, the arcane and ambiguous element which is so deliciously packaged, it leaves also little doubt as to nature of things, inclusive of all conceivable connotations. This, of course, would be a "statement", something that goes beyond mere "depiction".<br/> <br/>The tension between the emotional contrasts given here are simple, uncontrived and, to my senses, utterly credible and convincing, but it is also (or so it appears) an image with subtleties not immediately accessible to the casual viewer.<br/><br/><i>Message edited by author 2007-11-14 12:35:41.</i></td>', 'Textures, colour, raked lighting, tones, all these draw attention to much immaculate detail. The composition, however, is bold combining thirds and forths against a deep black space bleeding away the dimensions of objects framing it. This, of course, introduces some ambiguity via areas (inner vertical bone on the left and insect remains so sparsely lit, it is a challenge to identify). Very little visual information is given to go beyond guessing as to what exactly the three objects are that combine this image, which leaves us with mystery. What intrigues me though, is the balance of tack-sharp poise of detail (the obvious image facts) versus its opposite, the arcane and ambiguous element which is so deliciously packaged, it leaves also little doubt as to nature of things, inclusive of all conceivable connotations. This, of course, would be a "statement", something that goes beyond mere "depiction". The tension between the emotional contrasts given here are simple, uncontrived and, to my senses, utterly credible and convincing, but it is also (or so it appears) an image with subtleties not immediately accessible to the casual viewer.', '2007-11-14 12:10:13.000000', '2007-11-14 12:35:41.000000', 0),
